	/**
	 * 自己的资料（只为拿 sec_uid —— 拉「她自己的作品列表」要用）。
	 * 只读端点，不要 a_bogus。
	 */
	async selfProfile() {
		const r = await this.request({ path: '/aweme/v1/web/user/profile/self/' });
		const user = r.json?.user ?? r.json?.data?.user ?? null;
		return { ok: r.ok && user !== null && user !== undefined, user, raw: r };
	}

	/**
	 * 某个人的作品列表 —— 「按类型挑自己哪条视频分享」全靠这里的字段
	 * （desc / cha_list 话题 / duration / create_time / statistics），
	 * 不读画面、不做识别，跟 dsh-douyin-scroll 的 forward-pick 一个思路。
	 *
	 * ⚠️ 这个端点要 a_bogus：preimage 先按「完整 query」算（同 comment/list），
	 *    被拒（403 / 空列表）再退成「只含业务参数」（同写接口），两种线上都见过。
	 */
	async userPosts(secUid, { count = 20, cursor = '0' } = {}) {
		if (String(secUid ?? '') === '') return { ok: false, list: [], cursor: 0, hasMore: false, raw: null };
		const params = [
			['sec_user_id', String(secUid)],
			['count', String(count)],
			['max_cursor', String(cursor)],
			['locate_item_id', ''],
			['locate_query', 'false'],
			['show_live_replay_strategy', '1'],
			['need_time_list', '1'],
			['time_list_query', '0'],
			['whale_cut_token', ''],
			['cut_version', '1'],
			['publish_video_strategy_type', '2']
		];
		const referer = `${DOUYIN_WEB_ORIGIN}/user/self`;
		let r = await this.request({ path: '/aweme/v1/web/aweme/post/', params, aBogus: true, referer });
		let list = r.json?.aweme_list ?? r.json?.data?.aweme_list ?? [];
		if (!Array.isArray(list) || list.length === 0) {
			const r2 = await this.request({ path: '/aweme/v1/web/aweme/post/', params, aBogus: true, aBogusScope: 'business', referer });
			const l2 = r2.json?.aweme_list ?? r2.json?.data?.aweme_list ?? [];
			if (Array.isArray(l2) && l2.length > 0) { r = r2; list = l2; }
			else if (r.error === undefined) r = r2;
		}
		return {
			ok: r.ok && Array.isArray(list) && list.length > 0,
			list: Array.isArray(list) ? list : [],
			cursor: Number(r.json?.max_cursor ?? 0) || 0,
			hasMore: r.json?.has_more === 1 || r.json?.has_more === true,
			raw: r,
		};
	}
}

